<?php $m = $args['model'] ?? array(); $p = $m['profile'] ?? array(); $google = $m['google_state'] ?? 'unknown'; $google_states = array( 'not_connected', 'connected', 'needs_attention' ); $google_valid = in_array( $google, $google_states, true ); $payment = $m['payment_state'] ?? 'unknown'; $payment_states = array( 'pending_verification', 'confirmed', 'paid' ); ?>
<section class="dzn-tp-section" aria-labelledby="tp-profile"><div class="dzn-tp-heading"><div><p class="dzn-tp-kicker">مشخصات</p><h2 id="tp-profile">اطلاعات شخصی</h2></div></div><div class="dzn-tp-form-grid"><label>نام<input value="<?php echo esc_attr( $p['name'] ?? '' ); ?>"></label><label>ایمیل<input type="email" dir="ltr" value="<?php echo esc_attr( $p['email'] ?? '' ); ?>"></label><label>WhatsApp / همراه الزامی<input type="tel" dir="ltr" required value="<?php echo esc_attr( $p['mobile'] ?? '' ); ?>"></label><label>منطقهٔ زمانی<select><option><?php echo esc_html( $p['timezone_label'] ?? 'انتخاب نشده' ); ?></option></select></label><label>نوع تقویم<select><option value="gregorian"<?php selected( $p['calendar'] ?? '', 'gregorian' ); ?>>میلادی</option><option value="persian"<?php selected( $p['calendar'] ?? '', 'persian' ); ?>>خورشیدی / هجری شمسی</option></select></label></div><button class="dzn-button" type="button" data-dzn-tp-presentation>ذخیره در آینده</button><p class="dzn-tp-action-status" aria-live="polite"></p></section>
<section class="dzn-tp-section" aria-labelledby="tp-google"><div class="dzn-tp-heading"><div><p class="dzn-tp-kicker">کلاس آنلاین</p><h2 id="tp-google">اتصال Google</h2></div><span class="dzn-tp-state is-<?php echo esc_attr( $google_valid ? $google : 'unknown' ); ?>"><?php echo esc_html( $google_valid ? array( 'not_connected' => 'متصل نیست', 'connected' => 'متصل', 'needs_attention' => 'نیازمند توجه' )[ $google ] : 'وضعیت در دسترس نیست' ); ?></span></div><p>این بخش فقط وضعیت نمایشی دارد؛ OAuth، API یا ذخیرهٔ اعتبارنامه انجام نمی‌شود.</p><?php if ( $google_valid ) : ?><div class="dzn-tp-actions"><button class="dzn-button" type="button" data-dzn-tp-presentation><?php echo esc_html( 'needs_attention' === $google ? 'اتصال دوباره' : ( 'connected' === $google ? 'قطع اتصال' : 'اتصال Google' ) ); ?></button></div><?php endif; ?><p class="dzn-tp-action-status" aria-live="polite"></p></section>
<section class="dzn-tp-section" aria-labelledby="tp-availability"><div class="dzn-tp-heading"><div><p class="dzn-tp-kicker">زمان تهران</p><h2 id="tp-availability">زمان‌های در دسترس</h2></div><span>پیشنهاد، نه محدودیت</span></div><p class="dzn-tp-recommended">ساعت‌های پیشنهادی دلنوازان: ۱۶:۰۰ تا ۲۱:۰۰</p><div class="dzn-tp-availability"><?php foreach ( $m['availability'] ?? array() as $day ) : ?><article><h3><?php echo esc_html( $day['day'] ?? '' ); ?></h3><?php foreach ( $day['blocks'] ?? array() as $block ) : ?><span class="is-available"><?php echo esc_html( $block ); ?></span><?php endforeach; ?><?php if ( ! empty( $day['booked'] ) ) : ?><span class="is-booked">کلاس رزروشده: <?php echo esc_html( $day['booked'] ); ?></span><?php endif; ?><button type="button" data-dzn-tp-presentation>افزودن بازه</button></article><?php endforeach; ?></div><h3>استثناهای تاریخ‌دار</h3><ul><?php foreach ( $m['exceptions'] ?? array() as $exception ) : ?><li><?php echo esc_html( $exception ); ?></li><?php endforeach; ?></ul><button class="dzn-button" type="button" data-dzn-tp-presentation>ویرایش در آینده</button><p class="dzn-tp-action-status" aria-live="polite"></p></section>
<section class="dzn-tp-section" aria-labelledby="tp-payments"><div class="dzn-tp-heading"><div><p class="dzn-tp-kicker">نمایش مالی</p><h2 id="tp-payments">پرداخت‌ها و صورت‌حساب‌ها</h2></div><span class="dzn-tp-state"><?php echo esc_html( in_array( $payment, $payment_states, true ) ? array( 'pending_verification' => 'در انتظار بررسی', 'confirmed' => 'تأییدشده برای پرداخت', 'paid' => 'پرداخت‌شده' )[ $payment ] : 'وضعیت در دسترس نیست' ); ?></span></div><?php if ( in_array( $payment, $payment_states, true ) ) : ?><div class="dzn-tp-stats"><div><strong>۲۶</strong><span>کلاس این ماه</span></div><div><strong>۱۹٫۵</strong><span>ساعت تدریس</span></div><div><strong>—</strong><span>مبلغ از مرجع معتبر</span></div></div><article class="dzn-tp-statement"><strong>صورت‌حساب شهریور</strong><span>در انتظار بررسی مرجع مالی</span><button type="button" disabled>دریافت در آینده</button></article><?php endif; ?><p class="dzn-tp-help">پوسته قابلیت محاسبه یا تأیید پرداخت را ندارد.</p></section>
<section class="dzn-tp-section" aria-labelledby="tp-stats"><div class="dzn-tp-heading"><div><p class="dzn-tp-kicker">نمای کلی</p><h2 id="tp-stats">آمار تدریس</h2></div></div><div class="dzn-tp-stats"><?php foreach ( array( 'active_students' => 'هنرجوی فعال', 'lessons_month' => 'کلاس این ماه', 'hours_month' => 'ساعت تدریس', 'upcoming' => 'کلاس پیش رو', 'year_total' => 'کلاس امسال' ) as $key => $label ) : ?><div><strong><?php echo esc_html( $m['statistics'][ $key ] ?? '—' ); ?></strong><span><?php echo esc_html( $label ); ?></span></div><?php endforeach; ?></div></section>
<section class="dzn-tp-section"><h2>امنیت و مدیریت حساب</h2><p>رمز عبور و دسترسی حساب در یکپارچه‌سازی امن آینده مدیریت می‌شود.</p><button type="button" disabled>تغییر رمز در آینده</button></section><?php dzn_theme_teacher_portal_component( 'help' ); ?>
